import{_ as t,o as d,c as o,a4 as c}from"./chunks/framework.CQGI5ZO3.js";const f=JSON.parse('{"title":"xs-protocol(7)","description":"How xs talks to its remote helper, which features each option needs, and what happens with older helpers.","frontmatter":{"title":"xs-protocol(7)","description":"How xs talks to its remote helper, which features each option needs, and what happens with older helpers.","manual":"xs-protocol(7)","manualName":"Protocol & compatibility","sectionNumber":"7"},"headers":[],"relativePath":"protocol.md","filePath":"protocol.md"}'),r={name:"protocol.md"};function a(s,e,i,l,n,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="xs-protocol-7" tabindex="-1">xs-protocol(7) <a class="header-anchor" href="#xs-protocol-7" aria-label="Permalink to &quot;xs-protocol(7)&quot;">​</a></h1><div class="manual-deck"><strong>Protocol &amp; compatibility</strong><p>How xs talks to its remote helper, which features each option needs, and what happens with older helpers.</p></div><h2 id="overview" tabindex="-1">OVERVIEW <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;OVERVIEW {#overview}&quot;">​</a></h2><p>xs is not wire-compatible with rsync. A remote transfer runs <code>xs --server</code> on the other machine over a remote shell, normally ssh, and the two processes speak xs’s own pipelined protocol over the shell’s stdin and stdout. Paths travel as protocol data, never as shell text.</p><p>Every constant on this page is read from <code>src/common.h</code> and <code>src/remote.cpp</code> when the documentation is built, and <code>npm run check</code> fails if the copy here is out of date.</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">Constant</th><th scope="col">Value</th></tr></thead><tbody><tr><td>Current version</td><td><code>4</code></td></tr><tr><td>Oldest supported peer</td><td><code>3</code></td></tr><tr><td>Magic</td><td><code>XSYNC\\x01</code></td></tr><tr><td>Frame header</td><td>5 bytes: a 4-byte payload length and a 1-byte type</td></tr><tr><td>DATA block target</td><td>1 MiB of file data</td></tr><tr><td>Small-file limit</td><td>512 KiB; smaller files are packed together into shared blocks</td></tr><tr><td>Features assumed for a protocol-3 peer</td><td><code>PF_CORE</code>, <code>PF_ZSTD</code>, <code>PF_IDMAP</code>, <code>PF_SAFE_LINKS</code></td></tr></tbody></table></div><h2 id="versions" tabindex="-1">VERSIONS <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;VERSIONS {#versions}&quot;">​</a></h2><p>Each release speaks its own protocol, N, and the one before it, N−1. When a protocol-4 client meets a protocol-3 helper, it reconnects once at protocol 3 before opening the destination. A protocol-3 client can also use a protocol-4 helper. If the versions are further apart, the transfer falls back to rsync, or exits 2 with <code>--no-fallback</code>.</p><p>A protocol-3 peer is assumed to support only the core transfer, compression, name mapping and safe links. Any request beyond that (<code>-H</code>, <code>-X</code>, <code>-A</code>, <code>--bwlimit</code>, extended filters, structured output and so on) delegates to rsync before anything is written.</p><h2 id="negotiation" tabindex="-1">NEGOTIATION <a class="header-anchor" href="#negotiation" aria-label="Permalink to &quot;NEGOTIATION {#negotiation}&quot;">​</a></h2><ol><li>The client starts the helper: <code>ssh [-l user] host &lt;helper&gt; --server</code>. The helper is <code>--rsync-path</code> if given; otherwise a small shell snippet tries <code>xs</code> on <code>PATH</code>, then <code>~/.local/bin/xs</code>, then <code>XSYNC_REMOTE_PATH</code>. If none is found, the shell exits 127 and the transfer falls back to rsync.</li><li>The client sends <code>F_HELLO</code>: magic, version, role (the helper receives on a push and sends on a pull), its feature mask, and the frozen options.</li><li>The helper answers with its own <code>F_HELLO</code>. The negotiated features are the intersection of both masks. Unknown bits are ignored.</li><li>Each side checks that every feature the requested options need is in the intersection. If one is missing, the transfer falls back to rsync before any write, or exits 4 with <code>--no-fallback</code>. Optional features, such as resume or compression, are simply not used.</li><li>Options outside the frozen layout follow as separate configuration frames, each sent only when its feature was negotiated: I/O limits, xattrs, ACLs, <code>--chown</code>, sparse, <code>--link-dest</code>, relative paths, file lists, filters, deletion, pruning and output.</li></ol><h2 id="features" tabindex="-1">FEATURES <a class="header-anchor" href="#features" aria-label="Permalink to &quot;FEATURES {#features}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Feature</th><th scope="col">Value</th><th scope="col">Requested when</th><th scope="col">Without it</th></tr></thead><tbody><tr id="pf-core"><td><a class="option-anchor" href="#pf-core"><code>PF_CORE</code></a></td><td><code>1</code><br><small>bit 0</small></td><td>Always.</td><td>The peer cannot speak the native protocol. Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-zstd"><td><a class="option-anchor" href="#pf-zstd"><code>PF_ZSTD</code></a></td><td><code>2</code><br><small>bit 1</small></td><td>Always advertised.</td><td>Silent: data travels uncompressed. A protocol-3 helper asked for <code>-z</code> without it refuses with exit 4.</td></tr><tr id="pf-idmap"><td><a class="option-anchor" href="#pf-idmap"><code>PF_IDMAP</code></a></td><td><code>4</code><br><small>bit 2</small></td><td><code>-o</code>, <code>-g</code> or <code>--chown</code> without <code>--numeric-ids</code>: owners and groups are mapped by name.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>. Use <code>--numeric-ids</code> to avoid it.</td></tr><tr id="pf-safe-links"><td><a class="option-anchor" href="#pf-safe-links"><code>PF_SAFE_LINKS</code></a></td><td><code>8</code><br><small>bit 3</small></td><td><code>--safe-links</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-resume"><td><a class="option-anchor" href="#pf-resume"><code>PF_RESUME</code></a></td><td><code>16</code><br><small>bit 4</small></td><td>Advertised unless <code>-W</code>; used with <code>--partial</code>/<code>-P</code>.</td><td>Silent: interrupted files are sent in full.</td></tr><tr id="pf-output"><td><a class="option-anchor" href="#pf-output"><code>PF_OUTPUT</code></a></td><td><code>32</code><br><small>bit 5</small></td><td><code>--out-format</code>, <code>--log-file</code> or <code>--progress=json</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>. Plain <code>-v</code>/<code>-i</code> still work through ordinary messages.</td></tr><tr id="pf-dir-output"><td><a class="option-anchor" href="#pf-dir-output"><code>PF_DIR_OUTPUT</code></a></td><td><code>64</code><br><small>bit 6</small></td><td><code>--out-format</code> or <code>-ii</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-hlink"><td><a class="option-anchor" href="#pf-hlink"><code>PF_HLINK</code></a></td><td><code>128</code><br><small>bit 7</small></td><td><code>-H</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-delta"><td><a class="option-anchor" href="#pf-delta"><code>PF_DELTA</code></a></td><td><code>256</code><br><small>bit 8</small></td><td>Advertised unless <code>-W</code>.</td><td>Silent: changed large files are sent whole (or from a verified prefix).</td></tr><tr id="pf-list"><td><a class="option-anchor" href="#pf-list"><code>PF_LIST</code></a></td><td><code>512</code><br><small>bit 9</small></td><td><code>--list-only</code>, or listing a remote source.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-io-control"><td><a class="option-anchor" href="#pf-io-control"><code>PF_IO_CONTROL</code></a></td><td><code>1024</code><br><small>bit 10</small></td><td>Always advertised; required for a nonzero <code>--bwlimit</code> or <code>--timeout</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>. Without a limit it is silent, but no keep-alives are exchanged.</td></tr><tr id="pf-filters"><td><a class="option-anchor" href="#pf-filters"><code>PF_FILTERS</code></a></td><td><code>2048</code><br><small>bit 11</small></td><td>Filter rules beyond plain include/exclude: sides, merge, CVS, absolute, perishable or xattr rules.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-merge-filters"><td><a class="option-anchor" href="#pf-merge-filters"><code>PF_MERGE_FILTERS</code></a></td><td><code>4096</code><br><small>bit 12</small></td><td>Per-directory merge rules, including <code>-F</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-cvs-filters"><td><a class="option-anchor" href="#pf-cvs-filters"><code>PF_CVS_FILTERS</code></a></td><td><code>8192</code><br><small>bit 13</small></td><td><code>-C</code> or merge rules.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-delete-after"><td><a class="option-anchor" href="#pf-delete-after"><code>PF_DELETE_AFTER</code></a></td><td><code>16384</code><br><small>bit 14</small></td><td><code>--delete-after</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-prune-empty"><td><a class="option-anchor" href="#pf-prune-empty"><code>PF_PRUNE_EMPTY</code></a></td><td><code>32768</code><br><small>bit 15</small></td><td><code>-m</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-relative"><td><a class="option-anchor" href="#pf-relative"><code>PF_RELATIVE</code></a></td><td><code>65536</code><br><small>bit 16</small></td><td><code>-R</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-files-from"><td><a class="option-anchor" href="#pf-files-from"><code>PF_FILES_FROM</code></a></td><td><code>131072</code><br><small>bit 17</small></td><td><code>--files-from</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-xattrs"><td><a class="option-anchor" href="#pf-xattrs"><code>PF_XATTRS</code></a></td><td><code>262144</code><br><small>bit 18</small></td><td><code>-X</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-xattr-stream"><td><a class="option-anchor" href="#pf-xattr-stream"><code>PF_XATTR_STREAM</code></a></td><td><code>524288</code><br><small>bit 19</small></td><td><code>-X</code>; large values are streamed in chunks.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-acl-posix"><td><a class="option-anchor" href="#pf-acl-posix"><code>PF_ACL_POSIX</code></a><br><small>not advertised on macOS</small></td><td><code>1048576</code><br><small>bit 20</small></td><td><code>-A</code> between Linux hosts. Never advertised on macOS.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>. Mixed macOS/Linux ACL styles always take this path.</td></tr><tr id="pf-acl-darwin"><td><a class="option-anchor" href="#pf-acl-darwin"><code>PF_ACL_DARWIN</code></a><br><small>not advertised on Linux</small></td><td><code>2097152</code><br><small>bit 21</small></td><td><code>-A</code> between macOS hosts. Never advertised on Linux.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-acl-uuid"><td><a class="option-anchor" href="#pf-acl-uuid"><code>PF_ACL_UUID</code></a><br><small>not advertised on Linux</small></td><td><code>4194304</code><br><small>bit 22</small></td><td><code>-A</code> between macOS hosts, for unresolved UUID principals. Never advertised on Linux.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-atimes"><td><a class="option-anchor" href="#pf-atimes"><code>PF_ATIMES</code></a></td><td><code>8388608</code><br><small>bit 23</small></td><td><code>-U</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-crtimes"><td><a class="option-anchor" href="#pf-crtimes"><code>PF_CRTIMES</code></a><br><small>not advertised on Linux</small></td><td><code>16777216</code><br><small>bit 24</small></td><td><code>-N</code>. Never advertised on Linux.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-open-noatime"><td><a class="option-anchor" href="#pf-open-noatime"><code>PF_OPEN_NOATIME</code></a></td><td><code>33554432</code><br><small>bit 25</small></td><td><code>--open-noatime</code> or <code>-UU</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-executability"><td><a class="option-anchor" href="#pf-executability"><code>PF_EXECUTABILITY</code></a></td><td><code>67108864</code><br><small>bit 26</small></td><td><code>-E</code> without <code>-p</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-fileflags"><td><a class="option-anchor" href="#pf-fileflags"><code>PF_FILEFLAGS</code></a><br><small>not advertised on Linux</small></td><td><code>134217728</code><br><small>bit 27</small></td><td><code>--fileflags</code>. Never advertised on Linux.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-chown"><td><a class="option-anchor" href="#pf-chown"><code>PF_CHOWN</code></a></td><td><code>268435456</code><br><small>bit 28</small></td><td><code>--chown</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-sparse"><td><a class="option-anchor" href="#pf-sparse"><code>PF_SPARSE</code></a></td><td><code>536870912</code><br><small>bit 29</small></td><td><code>-S</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-link-dest"><td><a class="option-anchor" href="#pf-link-dest"><code>PF_LINK_DEST</code></a></td><td><code>1073741824</code><br><small>bit 30</small></td><td><code>--link-dest</code>.</td><td>Fallback to rsync before any write, or exit 4 with <code>--no-fallback</code>.</td></tr><tr id="pf-progress-ack"><td><a class="option-anchor" href="#pf-progress-ack"><code>PF_PROGRESS_ACK</code></a></td><td><code>2147483648</code><br><small>bit 31</small></td><td>A push with progress; required for a push dry run that prints its plan.</td><td>Silent for progress: the bar stays at zero until the helper finishes. A push dry run without <code>-q</code> falls back or exits 4.</td></tr><tr id="pf-stage-metrics"><td><a class="option-anchor" href="#pf-stage-metrics"><code>PF_STAGE_METRICS</code></a></td><td><code>4294967296</code><br><small>bit 32</small></td><td><code>-vv</code>.</td><td>Silent: no limiting-stage estimate.</td></tr><tr id="pf-progress-phase"><td><a class="option-anchor" href="#pf-progress-phase"><code>PF_PROGRESS_PHASE</code></a></td><td><code>8589934592</code><br><small>bit 33</small></td><td><code>--progress</code>.</td><td>Silent: the client shows only its own phases.</td></tr></tbody></table></div><p>Features that are never advertised on a platform are features its native filesystem layer cannot provide. Requesting one there fails before transfer, for example <code>-N</code> on Linux. <a href="options.html#source">The option reference</a> shows which features each option needs.</p><h2 id="frames" tabindex="-1">FRAMES <a class="header-anchor" href="#frames" aria-label="Permalink to &quot;FRAMES {#frames}&quot;">​</a></h2><p>Every frame is a 4-byte payload length, a 1-byte type and the payload, capped at 1 GiB. Each type has its own length and negotiation checks: a frame for a feature that was not negotiated is a protocol error, never ignored.</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">Type</th><th scope="col">Frame</th><th scope="col">Purpose</th></tr></thead><tbody><tr><td><code>1</code></td><td><code>F_HELLO</code></td><td>Opens the session. The client sends the magic, its version, its role, its feature mask (protocol 4) and the frozen options; the server answers with the negotiated features.</td></tr><tr><td><code>2</code></td><td><code>F_DIR</code></td><td>One directory listing, from sender to receiver, optionally zstd-packed.</td></tr><tr><td><code>3</code></td><td><code>F_NEED</code></td><td>The receiver’s answer to a directory: which files it wants, with resume prefixes and delta eligibility.</td></tr><tr><td><code>4</code></td><td><code>F_DATA</code></td><td>A block of file records (about 1 MiB), with a compression flag and an XXH3 checksum.</td></tr><tr><td><code>5</code></td><td><code>F_LIST_END</code></td><td>The sender has finished walking the source. In list mode, the final frame with status and count.</td></tr><tr><td><code>6</code></td><td><code>F_DATA_END</code></td><td>All data is sent; carries the sender’s exit status.</td></tr><tr><td><code>7</code></td><td><code>F_DONE</code></td><td>The receiver’s final frame: status and created/deleted counts.</td></tr><tr><td><code>8</code></td><td><code>F_MSG</code></td><td>A message in either direction: an output line, an error, or a fatal error with its exit code.</td></tr><tr><td><code>9</code></td><td><code>F_IDMAP</code></td><td>User and group names for the ids in the listing.</td></tr><tr><td><code>10</code></td><td><code>F_DEST</code></td><td>The receiver’s destination identity, sent first, so a destination inside the source can be refused.</td></tr><tr><td><code>11</code></td><td><code>F_OUTPUT</code></td><td>A structured itemize/log event from a remote receiver.</td></tr><tr><td><code>12</code></td><td><code>F_OUTPUT_CONFIG</code></td><td>Output settings: attributes, unchanged entries, mkpath, delete-before itemization.</td></tr><tr><td><code>13</code></td><td><code>F_DELTA_REQUEST</code></td><td>Asks the receiver for the block signature of an existing file.</td></tr><tr><td><code>14</code></td><td><code>F_DELTA_SIGNATURE</code></td><td>The block signature of the receiver’s copy.</td></tr><tr><td><code>15</code></td><td><code>F_DELTA_RETRY_ACK</code></td><td>Confirms that an abandoned delta attempt has been drained.</td></tr><tr><td><code>16</code></td><td><code>F_LIST_ENTRY</code></td><td>One listed entry in list-only mode.</td></tr><tr><td><code>17</code></td><td><code>F_IO_CONFIG</code></td><td>Bandwidth limit and idle timeout.</td></tr><tr><td><code>18</code></td><td><code>F_KEEPALIVE</code></td><td>An empty heartbeat, only when I/O control was negotiated.</td></tr><tr><td><code>19</code></td><td><code>F_FILTER_CONFIG</code></td><td>Extended filter rules, sent outside the frozen Hello.</td></tr><tr><td><code>20</code></td><td><code>F_DELETE_CONFIG</code></td><td>The delete-after setting.</td></tr><tr><td><code>21</code></td><td><code>F_PRUNE_CONFIG</code></td><td>The prune-empty-directories setting.</td></tr><tr><td><code>22</code></td><td><code>F_RELATIVE_CONFIG</code></td><td>The relative-paths setting.</td></tr><tr><td><code>23</code></td><td><code>F_FILES_CONFIG</code></td><td>Where the <code>--files-from</code> list is read, and its delimiter.</td></tr><tr><td><code>24</code></td><td><code>F_FILES_DATA</code></td><td>A chunk of the <code>--files-from</code> list.</td></tr><tr><td><code>25</code></td><td><code>F_FILES_END</code></td><td>The end of the <code>--files-from</code> list, with its byte count.</td></tr><tr><td><code>26</code></td><td><code>F_XATTR_CONFIG</code></td><td>The <code>-X</code> level.</td></tr><tr><td><code>27</code></td><td><code>F_XATTR_START</code></td><td>Begins a streamed extended-attribute value.</td></tr><tr><td><code>28</code></td><td><code>F_XATTR_CHUNK</code></td><td>A piece of a streamed extended-attribute value.</td></tr><tr><td><code>29</code></td><td><code>F_XATTR_END</code></td><td>Ends a streamed value, with its digest.</td></tr><tr><td><code>30</code></td><td><code>F_ACL_CONFIG</code></td><td>Enables ACL transfer.</td></tr><tr><td><code>31</code></td><td><code>F_CHOWN_CONFIG</code></td><td>The <code>--chown</code> user and group.</td></tr><tr><td><code>32</code></td><td><code>F_SPARSE_CONFIG</code></td><td>Enables sparse output.</td></tr><tr><td><code>33</code></td><td><code>F_LINKDEST_CONFIG</code></td><td>The <code>--link-dest</code> directories.</td></tr><tr><td><code>34</code></td><td><code>F_PROGRESS</code></td><td>Bytes and files a remote receiver has written, for the push progress bar.</td></tr><tr><td><code>35</code></td><td><code>F_STAGE</code></td><td>Read and network time from a remote sender, for the limiting-stage estimate.</td></tr><tr><td><code>36</code></td><td><code>F_PHASE</code></td><td>Deleting and verifying counts from the helper.</td></tr></tbody></table></div><p>Inside a <code>F_DATA</code> block, each file’s data is a sequence of records:</p><div class="manual-table-wrap"><table><thead><tr><th scope="col">Flag</th><th scope="col">Record</th><th scope="col">Meaning</th></tr></thead><tbody><tr><td><code>1</code></td><td><code>R_WHOLE</code></td><td>A whole small file (up to 512 KiB); many share one DATA block.</td></tr><tr><td><code>2</code></td><td><code>R_CHUNK</code></td><td>Part of a large file.</td></tr><tr><td><code>4</code></td><td><code>R_FAIL</code></td><td>The sender could not read a small file consistently (a read error, or the file changed while being read); it is not published.</td></tr><tr><td><code>8</code></td><td><code>R_END</code></td><td>The end of a large file: its final length, whether the source stayed unchanged while it was read, and fresh attributes.</td></tr><tr><td><code>16</code></td><td><code>R_LITERAL</code></td><td>Literal bytes in a delta transfer.</td></tr><tr><td><code>32</code></td><td><code>R_DELTA_END</code></td><td>The end of a delta transfer: the same status, plus a 16-byte checksum of the reconstructed file.</td></tr><tr><td><code>64</code></td><td><code>R_COPY</code></td><td>A run of blocks to copy from the receiver’s existing file.</td></tr></tbody></table></div><h2 id="push" tabindex="-1">A PUSH <a class="header-anchor" href="#push" aria-label="Permalink to &quot;A PUSH {#push}&quot;">​</a></h2><ol><li>Handshake and configuration, as above.</li><li>The receiving helper sends <code>F_DEST</code>: its destination’s identity. The sender refuses to continue if the destination lies inside the source.</li><li>The sender walks the source in parallel and streams one <code>F_DIR</code> per directory, with <code>F_IDMAP</code> names and streamed extended attributes, then <code>F_LIST_END</code>.</li><li>For each directory, the receiver compares it with the destination and answers <code>F_NEED</code>: the files it wants, with any verified resume prefix and whether a delta is possible.</li><li>The sender reads the needed files on its worker threads. Small files are packed many to a <code>F_DATA</code> block; large files are split into chunks; changed large files can use a delta (<code>F_DELTA_REQUEST</code>, <code>F_DELTA_SIGNATURE</code>, then copy and literal records).</li><li>While writing, the receiver reports progress (<code>F_PROGRESS</code>), file events (<code>F_OUTPUT</code>), phases (<code>F_PHASE</code>) and errors (<code>F_MSG</code>).</li><li>The sender finishes with <code>F_DATA_END</code>; the receiver finalizes directory attributes and deletions and replies <code>F_DONE</code>.</li></ol><p>A pull is the same exchange with the roles reversed: the helper sends, and the client receives and renders output locally. See <a href="architecture.html#remote">how it works</a> for a diagram.</p><h2 id="v3-layout" tabindex="-1">FROZEN PROTOCOL-3 LAYOUT <a class="header-anchor" href="#v3-layout" aria-label="Permalink to &quot;FROZEN PROTOCOL-3 LAYOUT {#v3-layout}&quot;">​</a></h2><p>The options inside <code>F_HELLO</code> keep the exact layout of protocol 3, so older peers can still parse them.</p><p>32 flags, one byte each, in this order:</p><p class="delegated-list"><code>recursive</code> <code>dirs</code> <code>links</code> <code>copy_links</code> <code>perms</code> <code>times</code> <code>group</code> <code>owner</code> <code>devices</code> <code>specials</code> <code>compress</code> <code>dry_run</code> <code>del</code> <code>delete_excluded</code> <code>force</code> <code>update</code> <code>checksum</code> <code>size_only</code> <code>ignore_times</code> <code>ignore_existing</code> <code>existing</code> <code>one_fs</code> <code>inplace</code> <code>omit_dir_times</code> <code>omit_link_times</code> <code>numeric_ids</code> <code>itemize</code> <code>partial</code> <code>clone</code> <code>direct_new</code> <code>ignore_errors</code> <code>safe_links</code></p><p>Then 7 integers as zigzag varints:</p><p class="delegated-list"><code>verbose</code> <code>compress_level</code> <code>max_size</code> <code>min_size</code> <code>modify_window</code> <code>jobs</code> <code>max_delete</code></p><p>Then a count and the plain include/exclude rules. Nothing may be added to, removed from or reordered in this layout.</p><h2 id="adding" tabindex="-1">ADDING A FEATURE <a class="header-anchor" href="#adding" aria-label="Permalink to &quot;ADDING A FEATURE {#adding}&quot;">​</a></h2><ul><li>A new optional frame, field or option gets its own feature bit. It must not change the protocol-3 layout or add unnegotiated fields to the Hello.</li><li>A receiver rejects frames for features that were not negotiated.</li><li>A requested semantic is never dropped silently. If the peer lacks a feature the user asked for, the transfer falls back or fails before any write.</li><li>When the supported window moves forward, a frozen N−1 peer is checked in as a fixture, like <code>tests/fixtures/protocol3.tar.gz</code>. Transfers are then tested in both directions, old client to new helper and new client to old helper, with fallback disabled (<code>tests/protocol_test.py</code>).</li></ul>',31)])])}const m=t(r,[["render",a]]);export{f as __pageData,m as default};
